describe('Promo Code Validation', () => {
    beforeEach(() => {
        cy.visit('/checkout'); // Adjust the URL to your checkout page
    });

    it('should display an error message for an expired promo code', () => {
        cy.get('input[name="promoCode"]').type('EXPIRED2023'); // Replace with the actual expired promo code
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'This promo code has expired.'); // Adjust the selector and message as needed
    });

    it('should not display an error message for a valid promo code', () => {
        cy.get('input[name="promoCode"]').type('VALID2023'); // Replace with the actual valid promo code
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('not.exist'); // Ensure no error message is displayed
    });
});
